var e=document.querySelector(`[data-seller-sales-chart]`);if(e&&window.ApexCharts){let t=document.getElementById(`salesChart`);try{let n=JSON.parse(e.dataset.sales||`[]`),r=JSON.parse(e.dataset.months||`[]`);new ApexCharts(t,{chart:{type:`area`,height:220,toolbar:{show:!1},sparkline:{enabled:!1}},series:[{name:`Sales (PHP)`,data:n}],xaxis:{categories:r},colors:[`#E8472A`],fill:{type:`gradient`,gradient:{shadeIntensity:1,opacityFrom:.4,opacityTo:.05}},stroke:{curve:`smooth`,width:2},dataLabels:{enabled:!1},yaxis:{labels:{formatter:e=>`PHP `+e.toLocaleString()}},tooltip:{y:{formatter:e=>`PHP `+e.toLocaleString()}},grid:{borderColor:`#e7e1d8`}}).render()}catch(e){console.error(`Unable to render seller sales chart.`,e)}}